def format_sig(value):
    """
    Format numbers with two significant digits.
    """
    if value == 0:
        return "0"
    elif abs(value) < 0.01 or abs(value) > 100:
        return f"{value:.2e}"  # 2 significant digits in scientific notation
    else:
        return f"{value:.2g}"  # Standard notation with 2 significant figures


def plot_histogram_and_kde(data, stats, bw_method=0.3, fn_name=''):
    """
    Plot the histogram and KDE of the data with key statistics marked.
    """
    kde = gaussian_kde(data, bw_method=bw_method)
    x = np.linspace(min(data), max(data), 1000)
    y = kde(x)

    gauss_color = 'lightslategrey'
    plt.figure(figsize=(8, 6))
    plt.hist(data, bins=30, density=True, color='darkgray', edgecolor='black', alpha=0.5)
    plt.plot(x, y, color=gauss_color, lw=2)
    plt.fill_between(x, y, color=gauss_color, alpha=0.3)

    # Add vertical lines for key statistics with formatted significant digits
    plt.axvline(stats["Mean"], color='crimson', linestyle='--', linewidth=1.5, label=f'Mean: {format_sig(stats["Mean"])}')
    plt.axvline(stats["Median"], color='steelblue', linestyle='--', linewidth=1.5, label=f'Median: {format_sig(stats["Median"])}')
    plt.axvline(stats["Q1"], color='purple', linestyle=':', linewidth=1.5, label=f'Q1: {format_sig(stats["Q1"])}')
    plt.axvline(stats["Q3"], color='purple', linestyle=':', linewidth=1.5, label=f'Q3: {format_sig(stats["Q3"])}')

    # Display min, max, std deviation as text on the plot
    plt.text(stats["Mean"] + stats["Standard Deviation"], 0.1, f'Std Dev: {format_sig(stats["Standard Deviation"])}', color='black', fontsize=10)
    plt.text(stats["Min"], 0.02, f'Min: {format_sig(stats["Min"])}', color='black', fontsize=10, ha='center')
    plt.text(stats["Max"], 0.02, f'Max: {format_sig(stats["Max"])}', color='black', fontsize=10, ha='center')

    # Add loss function name to the title
    plt.title(f"Combined Histogram and KDE with Statistics\n{fn_name}")
    plt.xlabel("Value")
    plt.ylabel("Density")
    plt.legend()
    # plt.grid(True)
    plt.show()


def display_statistics_table(stats, fn_name='', as_dataframe=True):
    """
    Display a table of the key statistics.
    """
    if as_dataframe:
        # Convert statistics to a DataFrame and display
        df = pd.DataFrame.from_dict(stats, orient='index', columns=['Value'])
        df.index.name = f"{fn_name}"
        display(df)
    else:
        fig, ax = plt.subplots(figsize=(5, 2))
        ax.axis("off")
        
        # Header title row
        table_data = [[f"{fn_name}", ""]]
        table_data += [[key, format_sig(value)] for key, value in stats.items()]
        
        table = ax.table(cellText=table_data, colLabels=["Statistic", "Value"], cellLoc="center", loc="center")
        table.auto_set_font_size(False)
        table.set_fontsize(10)
        table.scale(1.2, 1.2)
        
        # Style for header row
        header = table[0, 0]
        header.set_fontsize(12)
        header.set_text_props(weight="bold")
        plt.show()

# %% ../nbs/09_visualize.ipynb #5b42d2c4
def plot_dist(
    values,
    marginal="box",
    nbins=None,
    color=None,
    title=None,
    labels=None,
    opacity=0.65,
    barmode="overlay",
):
    """
    Plot one or more distributions with a Matplotlib-like Plotly layout.

    Parameters
    ----------
    values : array-like or list of array-like
        One distribution or multiple distributions.
    marginal : str or None
        One of {"box", "violin", None}.
    nbins : int or None
        Number of histogram bins.
    color : str or list of str or None
        One color, one per distribution, or None to use Plotly defaults.
    title : str or None
        Optional plot title.
    labels : list of str or None
        Names for each distribution.
    opacity : float
        Bar opacity when plotting multiple distributions.
    barmode : str
        Plotly bar mode, usually "overlay" or "group".
    """
    if isinstance(values, (list, tuple)) and len(values) > 0 and hasattr(values[0], "__len__"):
        dists = values
    else:
        dists = [values]

    if labels is None:
        labels = [f"dist_{i}" for i in range(len(dists))]

    if len(labels) != len(dists):
        raise ValueError("`labels` must have the same length as `values`.")

    frames = []
    for vals, label in zip(dists, labels):
        x = np.asarray(vals).ravel()
        x = x[~np.isnan(x)]
        frames.append(pd.DataFrame({"values": x, "dist": label}))

    df = pd.concat(frames, ignore_index=True)

    hist_kwargs = dict(
        data_frame=df,
        x="values",
        color="dist",
        marginal=marginal,
        hover_data=df.columns,
        nbins=nbins,
        template="simple_white",
        title=title,
        barmode=barmode,
        opacity=opacity,
    )

    if color is not None:
        if isinstance(color, str):
            colors = [color] * len(dists)
        else:
            colors = list(color)
            if len(colors) != len(dists):
                raise ValueError("`color` must be a string or a list with one color per distribution.")
        hist_kwargs["color_discrete_sequence"] = colors

    fig = px.histogram(**hist_kwargs)

    fig.update_traces(
        marker=dict(line=dict(color="black", width=0.8)),
    )

    fig.update_layout(
        font=dict(family="DejaVu Sans, Arial, sans-serif", size=12, color="black"),
        plot_bgcolor="white",
        paper_bgcolor="white",
        bargap=0.05,
        legend_title_text="",
    )

    fig.update_xaxes(
        showline=True,
        linewidth=1,
        linecolor="black",
        ticks="outside",
        tickwidth=1,
        tickcolor="black",
        showgrid=False,
    )

    fig.update_yaxes(
        showline=True,
        linewidth=1,
        linecolor="black",
        ticks="outside",
        tickwidth=1,
        tickcolor="black",
        showgrid=False,
    )

    fig.show()
    return fig

